body:
Interesting behavior I noticed between 1.31 and 1.32 clients.

https://pkg.go.dev/k8s.io/api/apps/v1#StatefulSetSpec field`VolumeClaimTemplates []v1.PersistentVolumeClaim` will have the TypeMeta set for `v1.PersistentVolumeClaim` when `Get()` a StatefulSet with 1.31 clients and in 1.32 clients the TypeMeta will be unset for the PersisentVolumeClaims. Interestingly there was a similar issue reported where items in a List from `List()` do not have TypeMeta set. https://github.com/kubernetes/kubernetes/issues/80609. During my testing I found that TypeMeta is not set for List items before 1.32 clients.

This stateful set example seems to be another instance of TypeMeta being dropped but in this case it's a regression between introduced by the 1.32 clients.

Below is testing example against a 1.31.0 Kind cluster.

main.go
```
package main

import (
	"bufio"
	"context"
	"flag"
	"fmt"
	"os"
	"path/filepath"

	appsv1 "k8s.io/api/apps/v1"
	apiv1 "k8s.io/api/core/v1"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/client-go/kubernetes"
	"k8s.io/client-go/tools/clientcmd"
	"k8s.io/client-go/util/homedir"
)

var (
	standardSCName         = "standard"
	standardRegionalSCName = "standard-rwo-regional"
	modeFilesystem         = apiv1.PersistentVolumeFilesystem
)

func createPVCTemplate(name string, storageClassName *string) apiv1.PersistentVolumeClaim {
	return apiv1.PersistentVolumeClaim{
		TypeMeta: metav1.TypeMeta{
			Kind:       "PersistentVolumeClaim",
			APIVersion: "v1",
		},
		ObjectMeta: metav1.ObjectMeta{
			Name: name,
		},
		Spec: apiv1.PersistentVolumeClaimSpec{
			VolumeMode:       &modeFilesystem,
			StorageClassName: storageClassName,
		},
	}
}

func main() {
	var kubeconfig *string
	if home := homedir.HomeDir(); home != "" {
		kubeconfig = flag.String("kubeconfig", filepath.Join(home, ".kube", "config"), "(optional) absolute path to the kubeconfig file")
	} else {
		kubeconfig = flag.String("kubeconfig", "", "absolute path to the kubeconfig file")
	}
	flag.Parse()

	config, err := clientcmd.BuildConfigFromFlags("", *kubeconfig)
	if err != nil {
		panic(err)
	}
	clientset, err := kubernetes.NewForConfig(config)
	if err != nil {
		panic(err)
	}

	// Test Create/Get/List/Delete for Stateful set
	statefulsetsClient := clientset.AppsV1().StatefulSets(apiv1.NamespaceDefault)

	statefulSet := &appsv1.StatefulSet{
		ObjectMeta: metav1.ObjectMeta{
			Name: "web",
		},
		Spec: appsv1.StatefulSetSpec{
			VolumeClaimTemplates: []apiv1.PersistentVolumeClaim{
				createPVCTemplate("volume", &standardRegionalSCName),
			},
			Selector: &metav1.LabelSelector{
				MatchLabels: map[string]string{"app": "nginx"},
			},
			ServiceName: "nginx",
			Replicas:    int32Ptr(2),
			Template: apiv1.PodTemplateSpec{
				ObjectMeta: metav1.ObjectMeta{
					Labels: map[string]string{"app": "nginx"},
				},
				Spec: apiv1.PodSpec{
					Containers: []apiv1.Container{
						{
							Name:  "nginx",
							Image: "nginx:latest",
							Ports: []apiv1.ContainerPort{
								{
									ContainerPort: 80,
									Name:          "web",
								},
							},
						},
					},
				},
			},
		},
	}

	// Create StatefulSet
        fmt.Println("Creating statefulset...")
	ssResult, err := statefulsetsClient.Create(context.TODO(), statefulSet, metav1.CreateOptions{})
        if err != nil {
                panic(err)
        }
        fmt.Printf("Created statefulset %q.\n", ssResult.GetObjectMeta().GetName())

        // Get StatefulSet
        prompt()
        fmt.Printf("Getting StatefulSet %s/%s\n", apiv1.NamespaceDefault, "web")
        ssGot, err := statefulsetsClient.Get(context.TODO(), "web", metav1.GetOptions{})
        if err != nil {
                panic(err)
        }
        fmt.Printf("%s, typeMeta Kind: %s APIVersion: %s\n", ssGot.Name, ssGot.TypeMeta.Kind, ssGot.TypeMeta.APIVersion)
	pvcTemplate := ssGot.Spec.VolumeClaimTemplates[0]
	fmt.Printf("%s, pvc[0] %s: TypeMeta Kind %s, APIVersion %s\n", ssGot.Name, pvcTemplate.Name, pvcTemplate.TypeMeta.Kind, pvcTemplate.TypeMeta.APIVersion)

	// List StatefulSets
        prompt()
	fmt.Printf("Listing statefulsets in namespace %q:\n", apiv1.NamespaceDefault)
        ssList, err := statefulsetsClient.List(context.TODO(), metav1.ListOptions{})
        if err != nil {
                panic(err)
	}
        for _, d := range ssList.Items {
                fmt.Printf(" * %s, typeMeta Kind: %s APIVersion: %s\n", d.Name, d.TypeMeta.Kind, d.TypeMeta.APIVersion)
        }

        // Delete StatefulSet
        prompt()
        fmt.Println("Deleting statefulset...")
        deletePolicy := metav1.DeletePropagationForeground
        if err := statefulsetsClient.Delete(context.TODO(), "web", metav1.DeleteOptions{
                PropagationPolicy: &deletePolicy,
        }); err != nil {
                panic(err)
        }
        fmt.Println("Deleted statefulset.")

}

func prompt() {
	fmt.Printf("-> Press Return key to continue.")
	scanner := bufio.NewScanner(os.Stdin)
	for scanner.Scan() {
		break
	}
	if err := scanner.Err(); err != nil {
		panic(err)
	}
	fmt.Println()
}

func int32Ptr(i int32) *int32 { return &i }
