/* fakenss.c */
#define _GNU_SOURCE
#include <pwd.h>
#include <string.h>
#include <dlfcn.h>
#include <errno.h>

int getpwnam_r(const char *name, struct passwd *pwd, char *buf,
               size_t buflen, struct passwd **result) {
    if (name && strcmp(name, "kubelet") == 0) {
        if (buflen < 64) { *result = NULL; return ERANGE; }
        char *p = buf;
        pwd->pw_name = p;   strcpy(p, "kubelet");          p += 8;
        pwd->pw_passwd = p; strcpy(p, "x");                p += 2;
        pwd->pw_gecos = p;  strcpy(p, "NSS-only");         p += 9;
        pwd->pw_dir = p;    strcpy(p, "/var/lib/kubelet"); p += 17;
        pwd->pw_shell = p;  strcpy(p, "/sbin/nologin");    p += 14;
        pwd->pw_uid = 991; pwd->pw_gid = 991;
        *result = pwd;
        return 0;
    }
    static int (*real)(const char *, struct passwd *, char *, size_t, struct passwd **);
    if (!real) real = dlsym(RTLD_NEXT, "getpwnam_r");
    if (!real) { *result = NULL; return ENOENT; }
    return real(name, pwd, buf, buflen, result);
}
