package topologycache

// Triage simulation (not for merge): drives the real TopologyCache.AddHints
// the way the EndpointSlice reconciler does while a DaemonSet-backed Service
// fills up incrementally, and counts endpoints whose hint is not their own
// zone. The packing rules mirror reconcileByPortMapping at this SHA.

import (
	"fmt"
	"math/rand"
	"sort"
	"testing"

	v1 "k8s.io/api/core/v1"
	discovery "k8s.io/api/discovery/v1"
	"k8s.io/apimachinery/pkg/api/resource"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"k8s.io/klog/v2/ktesting"
	"k8s.io/utils/ptr"
)

const simMaxEPS = 100

type simEP struct {
	addr, zone, node string
	arrive, serving  int
}

func simNodes(zones []string, perZone []int) []*v1.Node {
	var nodes []*v1.Node
	for zi, z := range zones {
		for i := 0; i < perZone[zi]; i++ {
			nodes = append(nodes, &v1.Node{
				ObjectMeta: metav1.ObjectMeta{Name: fmt.Sprintf("n-%s-%d", z, i), Labels: map[string]string{v1.LabelTopologyZone: z}},
				Status: v1.NodeStatus{
					Allocatable: v1.ResourceList{v1.ResourceCPU: resource.MustParse("2")},
					Conditions:  []v1.NodeCondition{{Type: v1.NodeReady, Status: v1.ConditionTrue}},
				},
			})
		}
	}
	return nodes
}

func (e *simEP) endpoint(now int) discovery.Endpoint {
	serving := e.serving <= now
	return discovery.Endpoint{
		Addresses:  []string{e.addr},
		Conditions: discovery.EndpointConditions{Ready: ptr.To(true), Serving: ptr.To(serving), Terminating: ptr.To(false)},
		Zone:       ptr.To(e.zone),
		NodeName:   ptr.To(e.node),
	}
}

type simResult struct {
	slices, mismatched, repairUpdates int
	hintsByZone                       map[string]int
	perSliceMismatch                  []int
}

func runSim(t *testing.T, zones []string, perZone []int, batch, servingDelay int, seed int64) simResult {
	return runSimOpt(t, zones, perZone, batch, servingDelay, seed, false)
}

func runSimOpt(t *testing.T, zones []string, perZone []int, batch, servingDelay int, seed int64, noSlowStart bool) simResult {
	logger, _ := ktesting.NewTestContext(t)
	rng := rand.New(rand.NewSource(seed))

	var eps []*simEP
	for zi, z := range zones {
		for i := 0; i < perZone[zi]; i++ {
			eps = append(eps, &simEP{addr: fmt.Sprintf("10.%d.%d.%d", zi+1, i/250, i%250+1), zone: z, node: fmt.Sprintf("n-%s-%d", z, i)})
		}
	}
	rng.Shuffle(len(eps), func(i, j int) { eps[i], eps[j] = eps[j], eps[i] })

	// Arrival schedule: DaemonSet slow start (1,2,4,8,...) capped at `batch`
	// endpoints per reconcile (the controller batches 500ms of pod events).
	idx, r, sz := 0, 0, 1
	if noSlowStart {
		sz = batch
	}
	for idx < len(eps) {
		n := sz
		if n > batch {
			n = batch
		}
		for k := 0; k < n && idx < len(eps); k++ {
			eps[idx].arrive, eps[idx].serving = r, r+servingDelay
			idx++
		}
		r++
		if sz < batch {
			sz *= 2
		}
	}
	lastReconcile := r + servingDelay + 1 // +1: one no-op reconcile at the end

	tc := NewTopologyCache()
	tc.SetNodes(logger, simNodes(zones, perZone))

	cache := map[string]*discovery.EndpointSlice{}
	var order []string
	nameCounter := 0
	repairUpdates := 0

	for now := 0; now <= lastReconcile; now++ {
		desired := map[string]*simEP{}
		for _, e := range eps {
			if e.arrive <= now {
				desired[e.addr] = e
			}
		}
		placed := map[string]bool{}
		var toUpdate, unchanged, toCreate []*discovery.EndpointSlice
		for _, name := range order {
			s := cache[name]
			changed := false
			newEPs := make([]discovery.Endpoint, 0, len(s.Endpoints))
			for _, ep := range s.Endpoints {
				e := desired[ep.Addresses[0]]
				placed[e.addr] = true
				want := e.endpoint(now) // desired endpoints carry no hints, as in podToEndpoint
				if *want.Conditions.Serving != *ep.Conditions.Serving {
					changed = true
				}
				newEPs = append(newEPs, want)
			}
			if changed {
				cp := s.DeepCopy()
				cp.Endpoints = newEPs
				toUpdate = append(toUpdate, cp)
			} else {
				unchanged = append(unchanged, s)
			}
		}
		var remaining []discovery.Endpoint
		for _, e := range eps {
			if e.arrive <= now && !placed[e.addr] {
				remaining = append(remaining, e.endpoint(now))
			}
		}
		pop := func() discovery.Endpoint { ep := remaining[0]; remaining = remaining[1:]; return ep }

		// step 2: fill slices already marked for update, fullest first.
		if len(remaining) > 0 && len(toUpdate) > 0 {
			sort.Slice(toUpdate, func(i, j int) bool { return len(toUpdate[i].Endpoints) > len(toUpdate[j].Endpoints) })
			for _, s := range toUpdate {
				for len(remaining) > 0 && len(s.Endpoints) < simMaxEPS {
					s.Endpoints = append(s.Endpoints, pop())
				}
			}
		}
		// step 3: tightest-fit unchanged slice if the rest fits in one, else new slices.
		for len(remaining) > 0 {
			var fill *discovery.EndpointSlice
			if len(remaining) < simMaxEPS && len(unchanged) > 0 {
				closest := simMaxEPS
				var pick int = -1
				for i, s := range unchanged {
					d := simMaxEPS - (len(remaining) + len(s.Endpoints))
					if d >= 0 && d < closest {
						closest, pick = d, i
					}
				}
				if pick >= 0 {
					fill = unchanged[pick].DeepCopy()
					unchanged = append(unchanged[:pick], unchanged[pick+1:]...)
					toUpdate = append(toUpdate, fill)
				}
			}
			if fill == nil {
				fill = &discovery.EndpointSlice{AddressType: discovery.AddressTypeIPv4}
				toCreate = append(toCreate, fill)
			}
			for len(remaining) > 0 && len(fill.Endpoints) < simMaxEPS {
				fill.Endpoints = append(fill.Endpoints, pop())
			}
		}

		si := &SliceInfo{ServiceKey: "ns/svc", AddressType: discovery.AddressTypeIPv4, ToCreate: toCreate, ToUpdate: toUpdate, Unchanged: unchanged}
		outCreate, outUpdate, _ := tc.AddHints(logger, si)
		if now == lastReconcile {
			repairUpdates = len(outCreate) + len(outUpdate)
		}
		for _, s := range outCreate {
			nameCounter++
			s.Name = fmt.Sprintf("s%d", nameCounter)
			cache[s.Name] = s
			order = append(order, s.Name)
		}
		for _, s := range outUpdate {
			cache[s.Name] = s
		}
	}

	res := simResult{slices: len(order), hintsByZone: map[string]int{}}
	for _, name := range order {
		m := 0
		for _, ep := range cache[name].Endpoints {
			if ep.Hints == nil || len(ep.Hints.ForZones) != 1 {
				m++
				continue
			}
			res.hintsByZone[ep.Hints.ForZones[0].Name]++
			if ep.Hints.ForZones[0].Name != *ep.Zone {
				m++
			}
		}
		res.perSliceMismatch = append(res.perSliceMismatch, m)
		res.mismatched += m
	}
	res.repairUpdates = repairUpdates
	return res
}

func TestScaleSim(t *testing.T) {
	zones := []string{"us-east-2a", "us-east-2b", "us-east-2c"}
	type cfg struct {
		name         string
		perZone      []int
		batch, delay int
	}
	cfgs := []cfg{
		{"100 nodes (34/33/33), batch 50", []int{34, 33, 33}, 50, 0},
		{"100 nodes, batch 10, serving +1", []int{34, 33, 33}, 10, 1},
		{"300 nodes (100/100/100), batch 50", []int{100, 100, 100}, 50, 0},
		{"1000 nodes (334/333/333), batch 50", []int{334, 333, 333}, 50, 0},
		{"2000 nodes (667/666/667), batch 50", []int{667, 666, 667}, 50, 0},
		{"2000 nodes, batch 50, serving +1", []int{667, 666, 667}, 50, 1},
		{"2000 nodes, batch 10", []int{667, 666, 667}, 10, 0},
		{"2000 nodes, batch 250", []int{667, 666, 667}, 250, 0},
		{"2000 nodes, batch 2000 (one shot)", []int{667, 666, 667}, 2000, 0},
	}
	for _, c := range cfgs {
		minM, maxM, sumM, slices, repair := 1<<30, 0, 0, 0, 0
		var last simResult
		for seed := int64(1); seed <= 5; seed++ {
			last = runSim(t, zones, c.perZone, c.batch, c.delay, seed)
			if last.mismatched < minM {
				minM = last.mismatched
			}
			if last.mismatched > maxM {
				maxM = last.mismatched
			}
			sumM += last.mismatched
			slices, repair = last.slices, repair+last.repairUpdates
		}
		t.Logf("%-40s slices=%-3d cross-zone hints over 5 seeds: min=%d max=%d avg=%.0f | final no-op reconcile rewrote %d slices | last seed hints/zone=%v per-slice=%v",
			c.name, slices, minM, maxM, float64(sumM)/5, repair, last.hintsByZone, last.perSliceMismatch)
	}
}

